try {
  const body = $input.first().json.body || $input.first().json;
  const toolCallList = body?.message?.toolCallList || [];
  if (toolCallList.length === 0) throw new Error('empty toolCallList');
  const toolCall = toolCallList[0];
  const toolCallId = toolCall.id || 'unknown';
  let args = {};
  try { args = typeof toolCall.function?.arguments === 'string' ? JSON.parse(toolCall.function.arguments) : (toolCall.function?.arguments || {}); } catch(e) { args = {}; }
  const doctorName = (args.doctorName || '').trim();
  const preferredDate = (args.preferredDate || '').trim();
  const preferredTime = (args.preferredTime || '').trim();
  if (!doctorName || !preferredDate) {
    return [{ json: { toolCallId, error: true, result: 'Doktor adı ve tarih bilgisi gereklidir. Hangi doktoru ve hangi tarihi tercih ediyorsunuz?' } }];
  }
  return [{ json: { toolCallId, doctorName, preferredDate, preferredTime, error: false } }];
} catch(e) {
  return [{ json: { toolCallId: 'unknown', error: true, result: 'İsteğinizi işlerken bir hata oluştu. Lütfen tekrar deneyin.' } }];
}

const extracted = $('Argümanları Çıkar').first().json;
const toolCallId = extracted.toolCallId;
const doctorName = extracted.doctorName;
const preferredDate = extracted.preferredDate;
const preferredTime = extracted.preferredTime;
const conflicts = $input.all().map(i => i.json).filter(r => r.id);
if (conflicts.length === 0) {
  const timeInfo = preferredTime ? `saat ${preferredTime}` : '09:00-18:00 saatleri arasında';
  return [{ json: { toolCallId, result: `${doctorName} doktoru ${preferredDate} tarihinde ${timeInfo} müsait. Randevu oluşturmak ister misiniz?` } }];
}
const bookedTimes = conflicts.map(c => c.appointment_time).filter(Boolean).join(', ');
return [{ json: { toolCallId, result: `${doctorName} doktorunun ${preferredDate} tarihinde dolu saatleri: ${bookedTimes}. Farklı bir saat veya tarih tercih eder misiniz?` } }];
